const fs = require('fs');
const { Resvg } = require('@resvg/resvg-js');

const W=3508, H=4961;
const c={bg:'#0b1320',panel:'#111d2f',panel2:'#0f1a2a',text:'#e8f0ff',muted:'#a9bdd8',accent:'#19d3ff',accent2:'#36e3c3',warn:'#ffd166',grid:'#1c2b42'};

function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function rect(x,y,w,h,r,fill,stroke='none',sw=0){return `<rect x='${x}' y='${y}' width='${w}' height='${h}' rx='${r}' ry='${r}' fill='${fill}' stroke='${stroke}' stroke-width='${sw}'/>`}
function text(x,y,t,size=30,weight=400,color=c.text,anchor='start'){return `<text x='${x}' y='${y}' font-family='DejaVu Sans' font-size='${size}' font-weight='${weight}' fill='${color}' text-anchor='${anchor}'>${esc(t)}</text>`}

let svg=[];
svg.push(`<svg xmlns='http://www.w3.org/2000/svg' width='${W}' height='${H}' viewBox='0 0 ${W} ${H}'>`);
svg.push(rect(0,0,W,H,0,c.bg));
for(let x=0;x<=W;x+=120) svg.push(`<line x1='${x}' y1='0' x2='${x}' y2='${H}' stroke='${c.grid}' stroke-width='1'/>`);
for(let y=0;y<=H;y+=120) svg.push(`<line x1='0' y1='${y}' x2='${W}' y2='${y}' stroke='${c.grid}' stroke-width='1'/>`);

const m=120, cw=W-2*m;
svg.push(rect(m,80,cw,600,36,c.panel2,'#284567',3));
svg.push(text(m+50,190,'Bot Mitigation at Scale:',92,700));
svg.push(text(m+50,300,'How Modern Web Security Services',92,700));
svg.push(text(m+50,410,'Protect Scientific Publishing Platforms',92,700));
svg.push(text(m+50,500,'IEEE Symposium on Security and Privacy (S&P)  |  Data-Driven Analysis of CDN-Based Challenge Pipelines',42,400,c.muted));
svg.push(text(m+50,570,'Key takeaway: challenge-based verification can cut scraping by 85% while sustaining 99.97% uptime with minimal user friction.',34,400,c.accent2));

svg.push(rect(m,760,cw,520,30,'#0f2136','#2f5c89',3));
svg.push(text(m+40,840,'Headline Metrics',56,700));
svg.push(text(m+60,1030,'85%',128,800,c.accent));
svg.push(text(m+60,1200,'Reduction in scraping attempts',33,400));
svg.push(text(m+60,1245,'after 6 months of deployment',33,400,c.muted));
svg.push(`<line x1='${W/2}' y1='860' x2='${W/2}' y2='1240' stroke='#2f5c89' stroke-width='3'/>`);
svg.push(text(W/2+60,1030,'99.97%',128,800,c.accent2));
svg.push(text(W/2+60,1200,'Uptime during 10× bot surge events',33,400));

const chipY=1320, chipW=(cw-40)/3;
const chips=[['~47%','Internet traffic from bots'],['30%','Bot traffic that is malicious'],['<2s','Legitimate user verification latency']];
chips.forEach((ch,i)=>{const x=m+i*(chipW+20); svg.push(rect(x,chipY,chipW,210,24,c.panel,'#2a4567',2)); svg.push(text(x+30,1410,ch[0],78,800,c.warn)); svg.push(text(x+30,1495,ch[1],33,400,c.muted));});

const s1y=1580;
svg.push(rect(m,s1y,cw,680,28,c.panel));
svg.push(text(m+36,s1y+90,'The Bot Threat Landscape for Academic Publishers',56,700));
svg.push(text(m+40,s1y+180,'Scientific publishing platforms host high-value intellectual property, making them prime targets for scraping, credential stuffing, and denial-of-service automation.',34,400));
svg.push(text(m+40,s1y+230,'Nearly half of web traffic is bot-generated, and a meaningful fraction is malicious. Without edge controls, origin infrastructure absorbs avoidable load and theft risk.',34,400,c.muted));
svg.push(text(m+60,s1y+340,'Traffic Composition Snapshot',44,700,c.accent));
svg.push(rect(m+60,s1y+390,cw-120,70,16,'#17263d')); svg.push(rect(m+60,s1y+390,(cw-120)*0.47,70,16,'#2b8cff'));
svg.push(text(m+80,s1y+438,'Bots ~47%',30,400,'#fff')); svg.push(text(m+80+(cw-120)*0.47,s1y+438,'  Human ~53%',30,400,c.muted));
svg.push(rect(m+60,s1y+500,cw-120,70,16,'#17263d')); svg.push(rect(m+60,s1y+500,(cw-120)*0.30,70,16,'#ff6b6b'));
svg.push(text(m+80,s1y+548,'Malicious bots 30% of bots',30,400,'#fff'));

const py=s1y+720, ph=1180;
svg.push(rect(m,py,cw,ph,28,c.panel2,'#2f5c89',3));
svg.push(text(m+36,py+90,'Challenge-Based Verification Pipeline',56,700));
svg.push(text(m+36,py+140,'Sequential edge workflow (technical core)',34,400,c.accent2));
const stages=[
['1. Request Interception','HTTP request routed through CDN edge node','<50 ms'],
['2. Threat Scoring','IP reputation + TLS fingerprint + behavior signals','~100 ms'],
['3. Challenge Issuance','Serve JavaScript/CAPTCHA when risk exceeds threshold','~500 ms'],
['4. Verification Check','Validate response; assign traceable Ray ID','~200 ms'],
['5. Access Grant','Forward verified user to origin with session token','<50 ms']];
const sx=m+60, sw=cw-120, sy=py+180, bh=155, gap=44;
stages.forEach((s,i)=>{const y=sy+i*(bh+gap); svg.push(rect(sx,y,sw,bh,22,i%2?'#102136':'#132842','#2a517a',2)); svg.push(text(sx+28,y+55,s[0],44,700,c.accent)); svg.push(text(sx+28,y+108,s[1],30,400)); svg.push(text(sx+sw-30,y+98,s[2],44,700,c.warn,'end')); if(i<4){const cx=sx+sw/2, y1=y+bh+10; svg.push(`<line x1='${cx}' y1='${y1}' x2='${cx}' y2='${y1+22}' stroke='${c.accent2}' stroke-width='6'/>`); svg.push(`<polygon points='${cx},${y1+30} ${cx-10},${y1+15} ${cx+10},${y1+15}' fill='${c.accent2}'/>`);} });
svg.push(text(m+60,py+ph-45,'End-to-end legitimate-user latency typically remains under 2 seconds.',34,400,c.muted));

const by=py+ph+40, ph2=H-by-90, gap=30, col=(cw-gap)/2;
svg.push(rect(m,by,col,ph2,28,c.panel));
svg.push(text(m+30,by+80,'Performance and Security Outcomes',44,700));
svg.push(text(m+30,by+150,'Metric',30,700,c.accent2));
svg.push(text(m+col-300,by+150,'Before',30,700,'#ff8e8e'));
svg.push(text(m+col-150,by+150,'After',30,700,'#8fffdc'));
svg.push(`<line x1='${m+26}' y1='${by+170}' x2='${m+col-26}' y2='${by+170}' stroke='#2d4563' stroke-width='2'/>`);
const rows=[['Scraping attempts/day','~1.2M','~180k'],['Origin server load (CPU)','78%','42%'],['Legitimate complaints/month','1,200','340'],['Uptime during surges','98.5%','99.97%']];
rows.forEach((r,i)=>{const y=by+220+i*72; svg.push(text(m+30,y,r[0],28,400)); svg.push(text(m+col-300,y,r[1],28,400,'#ffb3b3')); svg.push(text(m+col-150,y,r[2],28,400,'#adffe9'));});
svg.push(text(m+30,by+560,'Measured result: substantial abuse suppression with lower origin strain and sustained availability.',30,400,c.muted));

const rx=m+col+gap;
svg.push(rect(rx,by,col,ph2,28,c.panel));
svg.push(text(rx+30,by+80,'Usability vs. Security Trade-offs',44,700));
const t=[['Accessibility','Challenge flows should satisfy WCAG 2.1 to avoid excluding users.'],['Institutional Access','Allowlisting trusted university IP ranges reduces unnecessary prompts.'],['Transparency','Clear status messages improve trust during short verification delays.'],['Privacy','Threat detection telemetry requires explicit, understandable disclosure.']];
t.forEach((a,i)=>{const y=by+150+i*130; svg.push(text(rx+30,y,a[0],30,700,c.accent)); svg.push(text(rx+30,y+45,a[1],28,400));});
svg.push(text(W/2,H-30,'Case focus: scientific publishing platform protection via CDN-edge bot mitigation | Audience: security researchers & practitioners',30,400,'#7f95b2','middle'));

svg.push('</svg>');
const svgStr = svg.join('\n');
fs.writeFileSync('/app/output/final_poster.svg', svgStr);
const resvg = new Resvg(svgStr, { fitTo: { mode: 'width', value: W }, background: 'rgba(0,0,0,1)' });
const pngData = resvg.render().asPng();
fs.writeFileSync('/app/output/final_poster.png', pngData);
console.log('/app/output/final_poster.png');
